@page "/chat"
@rendermode InteractiveServer
@using sv_7058a85515c84a44938266ae39809d22.Services
@inject IChatService ChatService
@inject IJSRuntime JS

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    <!-- Left Sidebar: Channel List -->
    <aside class="chat-sidebar">
        <div class="sidebar-header">
            <h3>Channels</h3>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var channel in _channels)
                {
                    <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(channel)">
                        <div class="channel-name"># @channel.Name</div>
                        <div class="channel-description">@TruncateDescription(channel.Description)</div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    <!-- Main Message Area -->
    <main class="chat-main @(_threadOpen ? "" : "chat-main-wide")">
        @if (_activeChannel is not null)
        {
            <div class="main-header">
                <h2># @_activeChannel.Name</h2>
                <p>@_activeChannel.Description</p>
            </div>

            <div class="message-list" @ref="_messageListRef" @onscroll="OnMessageListScrollAsync">
                @if (_loadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var msg in _messages)
                    {
                        <div class="message-row" @onmouseenter="() => _hoveredMessageId = msg.Id"
                             @onmouseleave="() => _hoveredMessageId = null">
                            <div class="message-header">
                                <span class="message-author">@msg.Author</span>
                                <span class="message-time">@FormatRelativeTime(msg.SentAt)</span>
                            </div>
                            <div class="message-content">@msg.Content</div>

                            @if (msg.Reactions.Count > 0)
                            {
                                <div class="reaction-row">
                                    @foreach (var reaction in msg.Reactions)
                                    {
                                        <button class="reaction-badge" title="@string.Join(", ", reaction.Users)"
                                                @onclick="() => ToggleReactionAsync(msg.Id, reaction.Emoji)">
                                            @reaction.Emoji @reaction.Users.Count
                                        </button>
                                    }
                                </div>
                            }

                            @{ var replyCount = GetReplyCount(msg.Id); }
                            @if (replyCount > 0)
                            {
                                <button class="thread-link" @onclick="() => OpenThreadAsync(msg.Id)">
                                    @replyCount @(replyCount == 1 ? "reply" : "replies")
                                </button>
                            }

                            @if (_hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" @onclick="() => OpenThreadAsync(msg.Id)" title="Reply in thread">
                                        💬 Reply
                                    </button>
                                    <div class="emoji-picker-wrapper">
                                        <button class="action-btn" @onclick="() => ToggleEmojiPicker(msg.Id)" title="Add reaction">
                                            😀 React
                                        </button>
                                        @if (_emojiPickerMessageId == msg.Id)
                                        {
                                            <div class="emoji-picker">
                                                @foreach (var emoji in _commonEmojis)
                                                {
                                                    <button class="emoji-option" @onclick="() => PickEmojiAsync(msg.Id, emoji)">
                                                        @emoji
                                                    </button>
                                                }
                                            </div>
                                        }
                                    </div>
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea @bind="_newMessage" @bind:event="oninput"
                          @onkeydown="OnMessageKeyDownAsync"
                          placeholder="Message #@_activeChannel.Name" rows="2"></textarea>
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessage)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </main>

    <!-- Right Panel: Thread View -->
    @if (_threadOpen && _threadRootMessage is not null)
    {
        <aside class="chat-thread-panel">
            <div class="thread-header">
                <h3>Thread</h3>
                <button class="close-thread-btn" @onclick="CloseThread" title="Close thread">✕</button>
            </div>
            <div class="thread-root-quote">
                <span class="message-author">@_threadRootMessage.Author</span>
                <span class="message-time">@FormatRelativeTime(_threadRootMessage.SentAt)</span>
                <p>@_threadRootMessage.Content</p>
            </div>
            <div class="thread-replies">
                @if (_threadMessages is not null)
                {
                    @foreach (var reply in _threadMessages)
                    {
                        <div class="message-row">
                            <div class="message-header">
                                <span class="message-author">@reply.Author</span>
                                <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                            </div>
                            <div class="message-content">@reply.Content</div>
                            @if (reply.Reactions.Count > 0)
                            {
                                <div class="reaction-row">
                                    @foreach (var reaction in reply.Reactions)
                                    {
                                        <button class="reaction-badge" title="@string.Join(", ", reaction.Users)"
                                                @onclick="() => ToggleReactionAsync(reply.Id, reaction.Emoji)">
                                            @reaction.Emoji @reaction.Users.Count
                                        </button>
                                    }
                                </div>
                            }
                        </div>
                    }
                }
            </div>
            <div class="message-input-area">
                <textarea @bind="_threadReply" @bind:event="oninput"
                          @onkeydown="OnThreadKeyDownAsync"
                          placeholder="Reply in thread…" rows="2"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync" disabled="@string.IsNullOrWhiteSpace(_threadReply)">
                    Reply
                </button>
            </div>
        </aside>
    }
</div>

@code {
    private const int PageSize = 30;
    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    private List<Channel>? _channels;
    private int _activeChannelId;
    private Channel? _activeChannel;

    private List<Message>? _messages;
    private int _messagesSkip;
    private bool _loadingMore;
    private bool _allMessagesLoaded;

    private string _newMessage = "";
    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;

    // Thread state
    private bool _threadOpen;
    private int? _threadRootId;
    private Message? _threadRootMessage;
    private List<Message>? _threadMessages;
    private string _threadReply = "";

    // Reply counts per root message id (messages that have replies)
    private Dictionary<int, int> _replyCounts = new();

    private ElementReference _messageListRef;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0]);
        }
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        if (_activeChannelId == channel.Id) return;

        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _messages = null;
        _messagesSkip = 0;
        _allMessagesLoaded = false;
        _emojiPickerMessageId = null;

        await LoadMessagesAsync();
        await ChatService.MarkChannelReadAsync(channel.Id);
        await RefreshChannelsAsync();
    }

    private async Task LoadMessagesAsync()
    {
        var loaded = await ChatService.GetMessagesAsync(_activeChannelId, _messagesSkip, PageSize);
        _messages = loaded;
        _messagesSkip = loaded.Count;
        _allMessagesLoaded = loaded.Count < PageSize;
        BuildReplyCounts();
    }

    private async Task OnMessageListScrollAsync()
    {
        if (_loadingMore || _allMessagesLoaded) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop > 50) return;

        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messagesSkip, PageSize);
        if (older.Count > 0 && _messages is not null)
        {
            _messages.InsertRange(0, older);
            _messagesSkip += older.Count;
            BuildReplyCounts();
        }
        if (older.Count < PageSize)
        {
            _allMessagesLoaded = true;
        }

        _loadingMore = false;
    }

    private void BuildReplyCounts()
    {
        _replyCounts.Clear();
        if (_messages is null) return;
        foreach (var msg in _messages)
        {
            if (msg.ReplyToId.HasValue)
            {
                _replyCounts.TryGetValue(msg.ReplyToId.Value, out var count);
                _replyCounts[msg.ReplyToId.Value] = count + 1;
            }
        }
    }

    private int GetReplyCount(int messageId)
    {
        _replyCounts.TryGetValue(messageId, out var count);
        return count;
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessage) || _activeChannel is null) return;

        var sent = await ChatService.SendMessageAsync(_activeChannelId, _newMessage.Trim(), null);
        _messages ??= new();
        _messages.Add(sent);
        _messagesSkip++;
        _newMessage = "";

        await ScrollToBottomAsync();
    }

    private async Task OnMessageKeyDownAsync(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    private async Task OnThreadKeyDownAsync(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    // Thread operations
    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootId = rootMessageId;
        _threadRootMessage = _messages?.FirstOrDefault(m => m.Id == rootMessageId);
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadReply = "";
        _threadOpen = true;
        _emojiPickerMessageId = null;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootId = null;
        _threadRootMessage = null;
        _threadMessages = null;
        _threadReply = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReply) || _threadRootId is null || _activeChannel is null) return;

        var sent = await ChatService.SendMessageAsync(_activeChannelId, _threadReply.Trim(), _threadRootId);
        _threadMessages ??= new();
        _threadMessages.Add(sent);
        _threadReply = "";

        // Update reply count in main view
        _replyCounts.TryGetValue(_threadRootId.Value, out var count);
        _replyCounts[_threadRootId.Value] = count + 1;
    }

    // Reactions
    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task PickEmojiAsync(int messageId, string emoji)
    {
        _emojiPickerMessageId = null;
        await ToggleReactionAsync(messageId, emoji);
    }

    private async Task ToggleReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        // Refresh messages to show updated reactions
        if (_messages is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(_activeChannelId, 0, _messagesSkip);
            _messages = refreshed;
        }
    }

    // Helpers
    private async Task RefreshChannelsAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task ScrollToBottomAsync()
    {
        await JS.InvokeVoidAsync("eval",
            "setTimeout(() => { const el = document.querySelector('.message-list'); if(el) el.scrollTop = el.scrollHeight; }, 50)");
    }

    private static string TruncateDescription(string description)
    {
        return description.Length > 60 ? description[..57] + "…" : description;
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

