+    align-items: flex-end;
+    gap: 8px;
+    padding: 12px 20px;
+    border-top: 1px solid #ddd;
+    flex-shrink: 0;
+}
+
+    .message-input-area textarea {
+        flex: 1;
+        resize: none;
+        border: 1px solid #ccc;
+        border-radius: 6px;
+        padding: 8px 12px;
+        font-size: 0.9rem;
+        font-family: inherit;
+        outline: none;
+        transition: border-color 0.15s;
+    }
+
+        .message-input-area textarea:focus {
+            border-color: #1264a3;
+        }
+
+.send-btn {
+    background: #007a5a;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    padding: 8px 18px;
+    font-weight: 600;
+    font-size: 0.9rem;
+    cursor: pointer;
+    height: fit-content;
+    transition: background 0.15s;
+}
+
+    .send-btn:hover:not(:disabled) {
+        background: #005e44;
+    }
+
+    .send-btn:disabled {
+        opacity: 0.5;
+        cursor: default;
+    }
+
+/* ===== Thread Panel ===== */
+.chat-thread-panel {
+    width: 25%;
+    min-width: 260px;
+    display: flex;
+    flex-direction: column;
+    background: #fff;
+    border-left: 1px solid #ddd;
+    overflow: hidden;
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 12px 16px;
+    border-bottom: 1px solid #ddd;
+    flex-shrink: 0;
+}
+
+    .thread-header h3 {
+        margin: 0;
+        font-size: 1.05rem;
+    }
+
+.close-thread-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    color: #666;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+    .close-thread-btn:hover {
+        background: #f0f0f0;
+    }
+
+.thread-root-quote {
+    padding: 12px 16px;
+    background: #f9f9f9;
+    border-bottom: 1px solid #eee;
+    flex-shrink: 0;
+}
+
+    .thread-root-quote p {
+        margin: 6px 0 0;
+        font-size: 0.9rem;
+        color: #444;
+    }
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 8px 16px;
+}
+
